    const MONTHS = [/\bjan(?:uary)?\b/, /\bfeb(?:ruary)?\b/, /\bmar(?:ch)?\b/, /\bapr(?:il)?\b/, /\bmay\b/, /\bjune?\b/, /\bjuly?\b/, /\baug(?:ust)?\b/, /\bsept?(?:ember)?\b/, /\boct(?:ober)?\b/, /\bnov(?:ember)?\b/, /\bdec(?:ember)?\b/];
