      for (let k = 0; k < 3; k++) { const mm = ((mo - 1 + k) % 12) + 1, yy = y + Math.floor((mo - 1 + k) / 12), s = `${yy}-${pad(mm)}-${pad(d.day)}`; if (ok(yy, mm, d.day) && s >= today) return s; }
