      if (sav.length) lines.push(`Your savings ${sav.length === 1 ? "account holds" : "accounts hold"} ${money(sav.reduce((a, s) => a + Math.round(Number(s.balance_cents)), 0))} today; if some of it is for this, you need less.`);
