    const money = (c) => "$" + Math.floor(c / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",") + "." + String(c % 100).padStart(2, "0");
    const cap = (s) => s.replace(/\b\w/g, (c) => c.toUpperCase());
