    "welders": "welders-cutters-solderers-brazers",
    "rn": "registered-nurse",
    "nurse": "registered-nurse",
    "swe": "software-engineer",
    "ib-analyst": "investment-banking-analyst",
    "data-analyst": "data-analyst",
    "pm": "product-manager",
