        const bad = new Set(m.verbatim_sentence_reuse.value.map((x) => x.sentence));
        bodies.forEach((b, idx) => { if (proseSentencesOf(b).map(norm).some((s) => bad.has(s.slice(0, 90)) || [...bad].some((x) => s.startsWith(x.slice(0, 40))))) flagged.add(idx); });
